[{"legacy_id":0,"quote_text":"He who has a why to live can bear almost any how.","author":"Friedrich Nietzsche","theme":"Meaning","source":"Twilight of the Idols","reflection_prompt":"What, if anything, gives hardship a direction?"},{"legacy_id":1,"quote_text":"Man is the only creature who refuses to be what he is.","author":"Albert Camus","theme":"Freedom","source":"The Rebel","reflection_prompt":"What in yourself are you refusing today?"},{"legacy_id":2,"quote_text":"The unexamined life is not worth living.","author":"Socrates","theme":"Meaning","source":"Plato, Apology","reflection_prompt":"What have you accepted without examination?"},{"legacy_id":3,"quote_text":"We suffer more in imagination than in reality.","author":"Seneca","theme":"Suffering","source":"Letters to Lucilius","reflection_prompt":"Which anticipated pain never actually arrived?"},{"legacy_id":4,"quote_text":"Man is condemned to be free.","author":"Jean-Paul Sartre","theme":"Freedom","source":"Existentialism Is a Humanism","reflection_prompt":"Where is freedom experienced as a burden?"},{"legacy_id":5,"quote_text":"He who knows others is wise; he who knows himself is enlightened.","author":"Laozi","theme":"Freedom","source":"Dao De Jing, chapter 33 (translation varies)","reflection_prompt":"What do you know about yourself that knowledge of others cannot give?"},{"legacy_id":6,"quote_text":"It is not death that a man should fear, but he should fear never beginning to live.","author":"Marcus Aurelius","theme":"Mortality","source":"Meditations (translation varies)","reflection_prompt":"What part of your life keeps waiting to begin?"},{"legacy_id":7,"quote_text":"Love does not consist of gazing at each other, but in looking outward together in the same direction.","author":"Antoine de Saint-Exupéry","theme":"Love","source":"Wind, Sand and Stars","reflection_prompt":"What shared horizon holds a relationship together?"},{"legacy_id":8,"quote_text":"Whereof one cannot speak, thereof one must be silent.","author":"Ludwig Wittgenstein","theme":"Doubt","source":"Tractatus Logico-Philosophicus, 7","reflection_prompt":"What might silence reveal that explanation conceals?"},{"legacy_id":9,"quote_text":"Waste no more time arguing about what a good man should be. Be one.","author":"Marcus Aurelius","theme":"Action","source":"Meditations, 10.16","reflection_prompt":"When does thought become a way of postponing action?"},{"legacy_id":10,"quote_text":"All of humanity's problems stem from man's inability to sit quietly in a room alone.","author":"Blaise Pascal","theme":"Solitude","source":"Pensées (paraphrased translation)","reflection_prompt":"What would you meet if there were nothing to distract you?"},{"legacy_id":11,"quote_text":"Two things fill the mind with ever-increasing wonder: the starry sky above me and the moral law within me.","author":"Immanuel Kant","theme":"Beauty","source":"Critique of Practical Reason, conclusion (abridged translation)","reflection_prompt":"What is the relation between wonder and obligation?"},{"legacy_id":12,"quote_text":"How we spend our days is, of course, how we spend our lives.","author":"Annie Dillard","theme":"Time","source":"The Writing Life","reflection_prompt":"What does an ordinary Tuesday reveal about your life?"},{"legacy_id":13,"quote_text":"It is not enough to have a good mind; the main thing is to use it well.","author":"René Descartes","theme":"Action","source":"Discourse on Method","reflection_prompt":"Where has understanding not yet become practice?"},{"legacy_id":14,"quote_text":"Not knowing is most intimate.","author":"Zen koan (Dizang)","theme":"Doubt","source":"Book of Serenity","reflection_prompt":"Could uncertainty be a form of intimacy?"},{"legacy_id":15,"quote_text":"I never found the companion that was so companionable as solitude.","author":"Henry David Thoreau","theme":"Solitude","source":"Walden","reflection_prompt":"When is being alone a kind of presence?"},{"legacy_id":16,"quote_text":"The journey of a thousand miles begins with a single step.","author":"Laozi","theme":"Action","source":"Dao De Jing, chapter 64 (translation varies)","reflection_prompt":"Which beginning are you making too large?"},{"legacy_id":17,"quote_text":"The present moment is the only moment available to us, and it is the door to all moments.","author":"Thích Nhất Hạnh","theme":"Time","source":"Attributed; source needs verification","reflection_prompt":"What does attention change about time?"},{"legacy_id":18,"quote_text":"The strongest man in the world is he who stands most alone.","author":"Henrik Ibsen","theme":"Solitude","source":"An Enemy of the People (translation varies)","reflection_prompt":"When is standing alone conscience, and when is it pride?"},{"legacy_id":19,"quote_text":"The most beautiful experience we can have is the mysterious.","author":"Albert Einstein","theme":"Beauty","source":"The World As I See It (translation varies)","reflection_prompt":"What deserves wonder instead of explanation?"},{"legacy_id":20,"quote_text":"I think, therefore I am.","author":"René Descartes","theme":"Doubt","source":"Discourse on Method, Part IV","reflection_prompt":"What must be certain before you can doubt anything?"},{"legacy_id":21,"quote_text":"He who knows only his own side of the case knows little of that.","author":"John Stuart Mill","theme":"Doubt","source":"On Liberty, Chapter II","reflection_prompt":"Which opposing view would sharpen your own?"},{"legacy_id":22,"quote_text":"The philosophers have only interpreted the world, in various ways; the point is to change it.","author":"Karl Marx","theme":"Action","source":"Theses on Feuerbach, Thesis XI (translation varies)","reflection_prompt":"When should understanding become collective action?"},{"legacy_id":23,"quote_text":"I do not wish them to have power over men; but over themselves.","author":"Mary Wollstonecraft","theme":"Freedom","source":"A Vindication of the Rights of Woman, Chapter IV","reflection_prompt":"What is the difference between independence and dominance?"},{"legacy_id":24,"quote_text":"All things excellent are as difficult as they are rare.","author":"Baruch Spinoza","theme":"Meaning","source":"Ethics, Part V, Proposition 42, Scholium (translation varies)","reflection_prompt":"What is worth pursuing without any guarantee of ease?"},{"legacy_id":25,"quote_text":"The heart has its reasons, which reason does not know.","author":"Blaise Pascal","theme":"Love","source":"Pensées, fragment 277 (Brunschvicg; translation varies)","reflection_prompt":"Is there a form of understanding that reason alone cannot grasp?"},{"legacy_id":26,"quote_text":"Reason is, and ought only to be the slave of the passions.","author":"David Hume","theme":"Freedom","source":"A Treatise of Human Nature, Book II, Part III, Section III","reflection_prompt":"Does reason direct your desires, or serve them?"},{"legacy_id":27,"quote_text":"The life of man, solitary, poor, nasty, brutish, and short.","author":"Thomas Hobbes","theme":"Suffering","source":"Leviathan, Chapter XIII (excerpt)","reflection_prompt":"How much of a good life depends on other people?"},{"legacy_id":28,"quote_text":"A woman must have money and a room of her own if she is to write fiction.","author":"Virginia Woolf","theme":"Freedom","source":"A Room of One's Own, Chapter I","reflection_prompt":"What material conditions does freedom require?"},{"legacy_id":29,"quote_text":"There is nothing either good or bad, but thinking makes it so.","author":"William Shakespeare","theme":"Doubt","source":"Hamlet, Act II, Scene II","reflection_prompt":"How much do your judgments shape your world?"},{"legacy_id":30,"quote_text":"Man is by nature a political animal.","author":"Aristotle","theme":"Love","source":"Politics, Book I, 1253a (translation varies)","reflection_prompt":"Can a person truly flourish alone?"},{"legacy_id":31,"quote_text":"The true is the whole.","author":"G. W. F. Hegel","theme":"Meaning","source":"Phenomenology of Spirit, Preface (translation varies)","reflection_prompt":"Can something be understood apart from its relations?"},{"legacy_id":32,"quote_text":"The mind is its own place, and in itself can make a Heaven of Hell, a Hell of Heaven.","author":"John Milton","theme":"Doubt","source":"Paradise Lost, Book I","reflection_prompt":"Where does interpretation meet circumstance?"},{"legacy_id":33,"quote_text":"To be, or not to be, that is the question.","author":"William Shakespeare","theme":"Mortality","source":"Hamlet, Act III, Scene I","reflection_prompt":"What does it mean to bear an uncertain future?"},{"legacy_id":34,"quote_text":"Life can only be understood backwards; but it must be lived forwards.","author":"Søren Kierkegaard","theme":"Time","source":"Journals, 1843 (translation varies)","reflection_prompt":"How do you act before understanding catches up?"},{"legacy_id":35,"quote_text":"What is the use of a house if you haven't got a tolerable planet to put it on?","author":"Henry David Thoreau","theme":"Beauty","source":"Letter to Harrison Blake, 1860 (commonly quoted)","reflection_prompt":"What larger home makes your own life possible?"},{"legacy_id":36,"quote_text":"One does not become enlightened by imagining figures of light, but by making the darkness conscious.","author":"Carl Jung","theme":"Doubt","source":"The Philosophical Tree, Psychology and Alchemy, CW 13 (translation varies)","reflection_prompt":"What are you unwilling to notice about yourself?"},{"legacy_id":37,"quote_text":"The world is my representation.","author":"Arthur Schopenhauer","theme":"Doubt","source":"The World as Will and Representation, Book I (translation varies)","reflection_prompt":"How do perception and world fit together?"},{"legacy_id":38,"quote_text":"You must change your life.","author":"Rainer Maria Rilke","theme":"Action","source":"Archaic Torso of Apollo, New Poems (translation varies)","reflection_prompt":"What has beauty asked you to do?"},{"legacy_id":39,"quote_text":"The only thing we have to fear is fear itself.","author":"Franklin D. Roosevelt","theme":"Suffering","source":"First Inaugural Address, March 4, 1933","reflection_prompt":"What becomes possible when fear is named?"},{"legacy_id":40,"quote_text":"If liberty means anything at all, it means the right to tell people what they do not want to hear.","author":"George Orwell","theme":"Freedom","source":"Preface to Animal Farm, 'The Freedom of the Press'","reflection_prompt":"What does honest disagreement require?"},{"legacy_id":41,"quote_text":"I am no bird; and no net ensnares me.","author":"Charlotte Brontë","theme":"Freedom","source":"Jane Eyre, Chapter XXIII (excerpt)","reflection_prompt":"What does refusing a constraint look like?"}]
$quotes$::jsonb) AS r(legacy_id integer,quote_text text,author text,theme text,source text,reflection_prompt text)
)
INSERT INTO public.quotes(legacy_id,quote_text,author,theme,source,reflection_prompt,review_status,is_published)
